(function(){'use strict';
const api=()=>window.CAGE_BACKEND,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),safe=v=>{try{const u=new URL(v);return u.protocol==='https:'?u.href:'';}catch{return '';}};
const stages=['New','Saved','Applying','Submitted','Awarded','Unsuccessful','Archived'],types=['Tender / RFQ','Grant','Contract','Partnership'];
const sources=[['malawi','Malawi procurement','https://www.ppda.mw/tenders'],['un','UN procurement','https://www.ungm.org/Public/Notice'],['banks','Development banks','https://www.afdb.org/en/about-us/corporate-procurement/procurement-notices/current-solicitations'],['bilateral','Development partners','https://www.developpp.de/en/'],['innovation','Innovation & technology','https://www.unicefventurefund.org/apply-funding'],['climate','Climate & conservation','https://iucn.org/procurement/currently-running-tenders'],['discovery','Secondary discovery','https://opportunitydesk.org/']];
let root,dialog,db=null,loading=false,loaded=0,error='',epoch=0,selected=null,busy=false,scanBusy=false;let limit=25;let filters={tab:'Discover',q:'',type:'',region:'',eligibility:'',sort:'relevance'};try{filters={...filters,...JSON.parse(sessionStorage.getItem('cage-opportunity-filters')||'{}')};}catch{}
const today=()=>new Date(Date.now()+7200000).toISOString().slice(0,10);const date=v=>v?new Date(v).toLocaleString('en-GB',{timeZone:'Africa/Blantyre',dateStyle:'medium',timeStyle:'short'})+' CAT':'Not yet';
const track=r=>r.tracking||{stage:r.status==='Dismissed'?'Archived':r.status==='Intake created'?'Applying':r.status==='Reviewed'?'Saved':'New',version:0,checklist:[],links:{},verified:{}};
const verified=r=>track(r).verified?.confirmed?track(r).verified:{};
const due=r=>verified(r).deadline||r.deadline||'';
const days=r=>due(r)?Math.ceil((Date.parse(due(r)+'T00:00:00+02:00')-Date.parse(today()+'T00:00:00+02:00'))/86400000):null;
const geography=r=>verified(r).geography||r.raw_data?.geography||'Not stated';
const eligibility=r=>verified(r).eligibility||'Needs review';
const url=r=>safe(r.source_url);
function statusDate(r){const n=days(r);return n===null?(r.raw_data?.deadlineLabel==='Rolling'?'Rolling':'Deadline not stated'):n<0?'Past listed date':n===0?'Due today':`${n} days left`;}
function option(values,value){return values.map(x=>`<option value="${esc(x)}" ${value===x?'selected':''}>${esc(x)}</option>`).join('');}
function note(s){return `<p class="opp-note">${esc(s)}</p>`;}
function mount(){if(root)return;if(!document.querySelector('[data-view-panel="commercial"]'))return;const old=document.querySelector('.opportunity-monitor');old.hidden=true;const legacy=document.createElement('details');legacy.className='opp-legacy';legacy.innerHTML='<summary>Contract & delivery records</summary>';old.parentElement.append(legacy);const addRecord=document.getElementById('new-commercial-button');addRecord.textContent='+ Add contract / delivery record';addRecord.className='secondary-button';legacy.append(addRecord);for(const s of ['#commercial-metric-grid','.commercial-toolbar','#commercial-grid']){const el=document.querySelector(s);if(el)legacy.append(el);}root=document.createElement('section');root.className='opp-workspace';old.after(root);dialog=document.createElement('dialog');dialog.className='opp-dialog';document.body.append(dialog);dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();else selected=null;});root.addEventListener('click',click);root.addEventListener('change',change);root.addEventListener('input',input);dialog.addEventListener('click',dialogClick);render();refresh();}
function filtered(){return (db?.matches||[]).filter(r=>{if(window.CAGE_TEAMWORK&&!window.CAGE_TEAMWORK.opportunityMine(r))return false;const s=track(r).stage,n=days(r),tab=filters.tab;if(tab==='Discover'&&r.raw_data?.historical&&!verified(r).confirmed)return false;if(tab==='Discover'&&(['Archived','Awarded','Unsuccessful'].includes(s)||n!==null&&n<0))return false;if(tab==='Closing soon'&&(n===null||n<0||n>14||['Archived','Awarded','Unsuccessful','Submitted'].includes(s)))return false;if(stages.includes(tab)&&s!==tab)return false;if(tab==='Past deadlines'&&(n===null||n>=0))return false;return (!filters.q||`${r.title} ${r.organization} ${r.match_reason}`.toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.type||r.opportunity_type===filters.type)&&(!filters.region||geography(r)===filters.region)&&(!filters.eligibility||eligibility(r)===filters.eligibility);}).sort((a,b)=>filters.sort==='deadline'?(due(a)||'9999').localeCompare(due(b)||'9999'):filters.sort==='newest'?b.found_at.localeCompare(a.found_at):b.match_score-a.match_score);}
function render(){if(!root)return;const rows=filtered(),all=(db?.matches||[]).filter(r=>!window.CAGE_TEAMWORK||window.CAGE_TEAMWORK.opportunityMine(r)),last=db?.runs?.[0],good=db?.runs?.find(r=>r.status==='completed'),closing=all.filter(r=>{const n=days(r);return n!==null&&n>=0&&n<=7&&['Saved','Applying'].includes(track(r).stage);});
root.innerHTML=`<header class="opp-head"><div><p class="opp-eyebrow">CAGE / BUSINESS DEVELOPMENT</p><h2>Find the right next opportunity.</h2><p>Discover relevant work. Verify the fit. Keep every application moving.</p></div><div class="opp-header-actions">${db?.canEdit?'<button data-opp-add class="secondary-button">+ Add opportunity</button>':''}${db?.canScan?`<button data-opp-scan class="primary-button" ${scanBusy?'disabled':''}>${scanBusy?'Scanning…':'Scan now'}</button>`:''}<details class="opp-menu"><summary aria-label="More opportunity actions">⋯</summary><button data-opp-refresh>Refresh results</button><button data-opp-sources>Sources & scan health</button>${db?.canScan?'<button data-opp-settings>Scan settings</button>':''}</details></div></header>
<div class="opp-stats"><div><strong>${all.filter(r=>track(r).stage==='New').length}</strong><span>To review</span></div><div><strong>${all.filter(r=>['Saved','Applying'].includes(track(r).stage)).length}</strong><span>In your pipeline</span></div><div><strong>${closing.length}</strong><span>Due within 7 days</span></div><div><strong>${all.filter(r=>track(r).stage==='Submitted').length}</strong><span>Submitted</span></div></div>
<div class="opp-health ${last&&['failed','partial','interrupted'].includes(last.status)?'warning':''}"><span class="opp-dot"></span><span>${loading?'Refreshing stored results…':last?`Last scan: ${esc(last.status)} · ${esc(date(last.finished_at||last.started_at))}`:'No scan recorded yet.'} ${good?`<small>Last fully successful scan: ${esc(date(good.finished_at))}</small>`:''}</span><button data-opp-sources>View source health</button></div>
${error?`<p role="alert" class="opp-error">${esc(error)} Existing results are retained.</p>`:''}
${db?.settings?.reminders&&closing.length?`<div class="opp-reminder"><strong>${closing.length} saved application${closing.length===1?'':'s'} approaching deadline</strong><span>Review ownership and submission requirements.</span><button data-opp-tab="Closing soon">Review deadlines →</button></div>`:''}
<nav class="opp-tabs" aria-label="Opportunity views">${['Discover','New','Closing soon','Saved','Applying','Submitted','Archived','Past deadlines','All'].map(t=>`<button data-opp-tab="${t}" aria-pressed="${filters.tab===t}">${t}</button>`).join('')}</nav>
<div class="opp-filters"><input id="opp-search" type="search" value="${esc(filters.q)}" placeholder="Search opportunities or organisations" aria-label="Search opportunities"><select data-filter="type" aria-label="Opportunity type"><option value="">All types</option>${option(types,filters.type)}</select><select data-filter="region" aria-label="Geography"><option value="">All locations</option>${option(['Malawi','Southern Africa','Africa','International','Not stated'],filters.region)}</select><select data-filter="eligibility" aria-label="Eligibility"><option value="">All eligibility</option>${option(['Needs review','Direct applicant','Partner required','Not eligible'],filters.eligibility)}</select><select data-filter="sort" aria-label="Sort opportunities">${[['relevance','Best match'],['deadline','Deadline first'],['newest','Newest first']].map(([v,l])=>`<option value="${v}" ${filters.sort===v?'selected':''}>${l}</option>`).join('')}</select></div>
<div class="opp-result-count">${rows.length} opportunities <span>Relevance scores guide review; they do not confirm eligibility.</span></div>
<div class="opp-list">${rows.length?rows.slice(0,limit).map(r=>{const t=track(r),v=verified(r),n=days(r),owner=db.staff.find(p=>p.id===t.owner_id),duplicate=all.some(x=>x.id!==r.id&&x.title.toLowerCase().replace(/\W/g,'')===r.title.toLowerCase().replace(/\W/g,''));return `<article class="opp-row"><div class="opp-type-icon">${r.opportunity_type==='Grant'?'◈':r.opportunity_type==='Partnership'?'◇':'▤'}</div><div class="opp-row-body"><div class="opp-row-tags"><span>${esc(r.opportunity_type)}</span><span>${esc(geography(r))}</span>${r.raw_data?.changes?.length?'<span class="opp-change">Source updated</span>':''}${duplicate?'<span class="opp-change">Possible duplicate</span>':''}</div><h3>${esc(r.title)}</h3><p>${esc(v.organization||r.organization||'Organisation not stated')} <span>· ${esc(t.stage)}${owner?' · '+esc(owner.name):''}</span></p><small>${esc(eligibility(r))}${r.raw_data?.pageError?' · Source needs manual access':''}</small></div><div class="opp-row-deadline ${n!==null&&n<=7?'urgent':''}"><strong>${esc(statusDate(r))}</strong><small>${esc(due(r)||'Confirm on source')}${v.confirmed?' · Staff verified':''}</small></div><div class="opp-score"><strong>${Number(r.match_score)}</strong><small>relevance</small></div><button class="secondary-button" data-opp-open="${esc(r.id)}">Review →</button></article>`;}).join(''):`<div class="opp-empty"><div>◎</div><h3>${loading?'Loading opportunities…':all.length?'No results in this view':'Your next opportunity starts here'}</h3><p>${all.length?'Adjust your filters to see more opportunities.':'Run a scan or add a notice. Source failures and missing details will be shown clearly.'}</p></div>`}</div>${rows.length>limit?'<div class="opp-save"><button class="secondary-button" data-opp-more>Show more opportunities</button></div>':''}`;}
async function refresh(force=false){if(loading||!api()?.opportunityDashboard||!api()?.isProduction()||(!force&&Date.now()-loaded<60000))return;loading=true;const token=epoch;render();try{const data=await api().opportunityDashboard();if(token!==epoch)return;db=data;loaded=Date.now();error='';}catch(e){if(token===epoch){error=e.message;if(/access required|permission|sign in/i.test(error))db=null;}}finally{if(token===epoch){loading=false;render();}}}
function saveFilters(){try{sessionStorage.setItem('cage-opportunity-filters',JSON.stringify(filters));}catch{}}
function change(e){if(e.target.dataset.filter){limit=25;filters[e.target.dataset.filter]=e.target.value;saveFilters();render();}}
function input(e){if(e.target.id==='opp-search'){const pos=e.target.selectionStart;filters.q=e.target.value;saveFilters();render();const el=root.querySelector('#opp-search');el.focus();el.setSelectionRange(pos,pos);}}
async function click(e){const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-opp-more')){limit+=25;render();}else if(b.dataset.oppTab){limit=25;filters.tab=b.dataset.oppTab;saveFilters();render();}else if(b.dataset.oppOpen)open(b.dataset.oppOpen);else if(b.hasAttribute('data-opp-refresh'))refresh(true);else if(b.hasAttribute('data-opp-sources'))sourceDialog();else if(b.hasAttribute('data-opp-settings'))settingsDialog();else if(b.hasAttribute('data-opp-add'))addDialog();else if(b.hasAttribute('data-opp-scan')){if(scanBusy)return;scanBusy=true;error='';render();try{const r=await api().scanOpportunities();window.CAGE_APP.showToast(r.message||'Scan finished.');}catch(err){error=err.message;}finally{const err=error;scanBusy=false;await refresh(true);if(err){error=err;render();}}}}
function shell(title,body){dialog.innerHTML=`<div class="opp-dialog-head"><h2>${esc(title)}</h2><button type="button" data-opp-close aria-label="Close">×</button></div>${body}<p class="opp-error" role="alert"></p>`;if(!dialog.open)dialog.showModal();}
function field(name,label,value='',type='text',extra=''){return `<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function select(name,label,values,value){return `<label class="field">${esc(label)}<select name="${name}">${option(values,value)}</select></label>`;}
function open(id){const r=db?.matches.find(x=>x.id===id);if(!r)return;selected=id;const t=track(r),v=verified(r),raw=r.raw_data||{},state=window.CAGE_APP.getState();const checks=t.checklist?.length?t.checklist:[{label:'Confirm eligibility and applicant route',done:false},{label:'Review scope, budget and mandatory documents',done:false},{label:'Complete internal review before submission',done:false}];
shell(r.title,`<div class="opp-detail-meta"><span>${esc(r.opportunity_type)}</span><span>${esc(statusDate(r))}</span>${url(r)?`<a href="${esc(url(r))}" target="_blank" rel="noopener noreferrer">Open source ↗</a>`:''}</div><p>${esc(r.match_reason)}</p>
<dl class="opp-facts"><div><dt>Organisation</dt><dd>${esc(v.organization||r.organization||'Not stated')}</dd></div><div><dt>Value / budget</dt><dd>${esc(v.value||raw.estimatedValue||'Not stated')}</dd></div><div><dt>Deadline</dt><dd>${esc(due(r)||raw.deadlineLabel||'Not stated')}</dd></div><div><dt>Timezone</dt><dd>${esc(v.timezone||raw.timezone||'Not stated')}</dd></div><div><dt>Eligibility</dt><dd>${esc(eligibility(r))}</dd></div><div><dt>Source check</dt><dd>${esc(date(raw.checkedAt))}</dd></div></dl>
${note(raw.pageError||raw.routeHint||'Verify the original notice before applying.')}<form id="opp-track-form"><fieldset ${db.canEdit?'':'disabled'}><div class="opp-form-grid">${select('stage','Application status',stages,t.stage)}<label class="field">Owner<select name="owner_id"><option value="">Unassigned</option>${db.staff.map(p=>`<option value="${esc(p.id)}" ${p.id===t.owner_id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${memberSelect(t.members||[])}${select('decision','Bid / no-bid decision',['Undecided','Bid','No bid'],t.decision||'Undecided')}${field('submission_reference','Submission reference',t.submission_reference,'text','maxlength="300"')}${field('submitted_on','Date submitted',t.submitted_on,'date',`max="${today()}"`)}</div><label class="field">Working notes<textarea name="notes" rows="3" maxlength="10000">${esc(t.notes)}</textarea></label>
<details open><summary>Preparation checklist</summary><div class="opp-checks">${checks.map((c,i)=>`<label><input type="checkbox" name="check${i}" ${c.done?'checked':''}> ${esc(c.label)}</label>`).join('')}</div>${field('new_check','Add a checklist item','','text','maxlength="200"')}</details>
<details><summary>Verify notice details</summary>${note('Only confirm details after checking the source. Your name and verification time are recorded.')}<div class="opp-form-grid">${field('organization','Issuing organisation',v.organization||'','text','maxlength="300"')}${field('value','Published budget and currency',v.value||'','text','maxlength="200"')}${field('deadline','Confirmed deadline date',v.deadline||r.deadline||'','date')}${field('timezone','Deadline time and timezone',v.timezone||'','text','maxlength="150"')}${select('geography','Geography',['Not stated','Malawi','Southern Africa','Africa','International'],v.geography||geography(r))}${select('eligibility','Applicant route',['Needs review','Direct applicant','Partner required','Not eligible'],eligibility(r))}</div><label class="field">Required documents / eligibility evidence<textarea name="requirements" rows="3" maxlength="3000">${esc(v.requirements||'')}</textarea></label><label><input name="confirmed" type="checkbox" ${v.confirmed?'checked':''}> I checked these details against the source.</label></details>
<details><summary>Link existing CRM or project records</summary>${['deal','project'].map(k=>`<label class="field">${k==='deal'?'CRM opportunity':'Project'}<select name="${k}"><option value="">Not linked</option>${(state[k==='deal'?'deals':'projects']||[]).map(x=>`<option value="${esc(x.id)}" ${t.links?.[k]===x.id?'selected':''}>${esc(x.name||x.title)}</option>`).join('')}</select></label>`).join('')}</details>
</fieldset>${db.canEdit?'<div class="opp-save"><button class="primary-button">Save changes</button></div>':note('You have view access.')}</form>
<details><summary>Source evidence & changes</summary>${v.confirmed?note('Verified by '+(db.staff.find(p=>p.id===v.by)?.name||'staff')+' · '+date(v.at)):''}${note(raw.verification||'Legacy result — verify against the source.')}${raw.deadlineEvidence?`<p><strong>Detected deadline text:</strong> ${esc(raw.deadlineEvidence)}</p>`:''}<p class="opp-excerpt">${esc(raw.summary||'No source excerpt stored.')}</p>${(raw.changes||[]).map(c=>`<p>${esc(date(c.at))} · ${esc(c.note)}</p>`).join('')}${note('Source excerpts and keyword-based relevance are not a verified eligibility decision.')}</details><details><summary>Supporting files</summary><div id="opp-files">Loading files…</div>${db.canEdit?'<label class="field">Upload supporting file<input type="file" id="opp-file"></label><button type="button" data-opp-upload>Upload file</button>':''}</details>`);
const version=t.version;dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();if(busy)return;const f=e.currentTarget,v=Object.fromEntries(new FormData(f));const checklist=checks.map((c,i)=>({...c,done:f.elements['check'+i].checked}));if(v.new_check.trim())checklist.push({label:v.new_check.trim(),done:false});await mutate(()=>api().opportunitySave(id,version,{stage:v.stage,owner_id:v.owner_id,members:new FormData(f).getAll('members'),decision:v.decision,notes:v.notes,submission_reference:v.submission_reference,submitted_on:v.submitted_on,checklist,links:{deal:v.deal,project:v.project},verified:{confirmed:f.elements.confirmed.checked,organization:v.organization,value:v.value,deadline:v.deadline,timezone:v.timezone,geography:v.geography,eligibility:v.eligibility,requirements:v.requirements}}));};loadFiles(id);}
async function loadFiles(id){const token=epoch;try{const rows=await api().opportunityFiles(id);if(token!==epoch||selected!==id||!dialog.querySelector('#opp-files'))return;dialog.querySelector('#opp-files').innerHTML=rows.length?rows.map(f=>`<p><button type="button" data-opp-file="${esc(f.storage_path)}">${esc(f.file_name)}</button></p>`).join(''):'No supporting files yet.';}catch(e){if(selected===id&&dialog.querySelector('#opp-files'))dialog.querySelector('#opp-files').textContent=e.message;}}
async function mutate(fn){busy=true;const token=epoch;dialog.querySelectorAll('button').forEach(b=>b.disabled=true);try{const result=await fn();if(token!==epoch)return;db=result;loaded=Date.now();dialog.close();selected=null;render();window.CAGE_APP.showToast('Saved.');}catch(e){if(token===epoch)dialog.querySelector('.opp-error').textContent=e.message;}finally{if(token===epoch){busy=false;dialog.querySelectorAll('button').forEach(b=>b.disabled=false);}}}
async function dialogClick(e){const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-opp-close')&&!busy){dialog.close();selected=null;}if(b.dataset.oppFile){try{const link=await api().fileUrl(b.dataset.oppFile);const a=document.createElement('a');a.href=link;a.target='_blank';a.rel='noopener';a.click();}catch(err){dialog.querySelector('.opp-error').textContent=err.message;}}if(b.hasAttribute('data-opp-upload')){const file=dialog.querySelector('#opp-file').files[0];if(!file||busy)return;const id=selected,token=epoch;busy=true;b.disabled=true;try{await api().uploadFile(file,'opportunity',id);if(token!==epoch)return;await loadFiles(id);dialog.querySelector('#opp-file').value='';}catch(err){if(token===epoch)dialog.querySelector('.opp-error').textContent=err.message;}finally{if(token===epoch){busy=false;b.disabled=false;}}}}
function sourceDialog(){selected=null;const last=db?.runs?.[0];shell('Sources & scan health',`${note('Discovery checks selected official listings and rotating-domain search feeds. It does not exhaustively scan every portal. Login-only pages and unsupported documents need manual review.')}<div class="opp-source-list">${sources.map(([id,name,u])=>{const r=last?.sources?.find(x=>x.id===id);return `<article><div><strong>${esc(name)}</strong><p>${esc(r?.error||r?.method||'Not yet checked')}${r?.count!==undefined?' · '+r.count+' search results':''}</p></div><span class="opp-source-status">${db?.settings.disabled_sources?.includes(id)?'Disabled':esc(r?.status||'Not checked')}</span><a href="${u}" target="_blank" rel="noopener noreferrer">Open ↗</a></article>`;}).join('')}</div><p><a href="https://maneps.mw/" target="_blank" rel="noopener noreferrer">Open MANePS for direct procurement checks ↗</a></p><h3>Discovery summary</h3>${note(last?.sources?.find(x=>x.id==='pipeline')?.method||'Run a scan with the updated scanner to see candidate and exclusion counts.')}<h3>Recent scans</h3>${(db?.runs||[]).map(r=>`<p>${esc(date(r.started_at))} · ${esc(r.status)} · ${r.added} new / ${r.updated} changed / ${r.checked} checked${r.error?' · '+esc(r.error):''}</p>`).join('')||note('No scans recorded.')}${note('Scans check up to 40 candidate pages per run, including up to 12 saved notices, prioritising unseen notices and rotating remaining candidates. Scheduled scans need the Supabase Cron job installed.')}`);}
function settingsDialog(){selected=null;const s=db.settings;shell('Scan settings',`<form id="opp-settings-form">${select('frequency','Discovery frequency',['twice_daily','daily','manual'],s.frequency)}${note('Twice daily: 07:00 and 19:00 CAT. Daily: 07:00 CAT. These schedules require the Cron setup included with this update.')}<label><input name="reminders" type="checkbox" ${s.reminders?'checked':''}> Show deadline reminders in this workspace</label><h3>Discovery sources</h3>${sources.map(([id,name])=>`<label class="opp-setting-check"><input name="source-${id}" type="checkbox" ${s.disabled_sources?.includes(id)?'':'checked'}> ${name}</label>`).join('')}${note('This update uses source excerpts and rule-based ranking without paid AI calls. It does not automatically email staff or contact clients.')}<div class="opp-save"><button class="primary-button">Save settings</button></div></form>`);dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;mutate(()=>api().opportunitySettings({frequency:f.elements.frequency.value,reminders:f.elements.reminders.checked,disabled_sources:sources.filter(([id])=>!f.elements['source-'+id].checked).map(([id])=>id)}));};}
function memberSelect(selected){return `<details class="teamwork-picker"><summary>Add members</summary><div>${(db?.staff||[]).map(p=>`<label><input type="checkbox" name="members" value="${esc(p.id)}" ${selected.includes(p.id)?'checked':''}> ${esc(p.name)}</label>`).join('')}</div></details>`;}
function addDialog(){selected=null;shell('Add an opportunity',`<form>${field('title','Opportunity title','','text','required minlength="5" maxlength="500"')}${field('organization','Issuing organisation','','text','maxlength="300"')}${select('type','Type',types,types[0])}${field('url','Source URL','','url','required maxlength="2000"')}${memberSelect([])}${note('Add the direct notice link. You can verify dates and eligibility after saving.')}<div class="opp-save"><button class="primary-button">Add opportunity</button></div></form>`);dialog.querySelector('form').onsubmit=e=>{e.preventDefault();mutate(async()=>{const result=await api().opportunityAdd({...Object.fromEntries(new FormData(e.currentTarget)),members:new FormData(e.currentTarget).getAll('members')});return result.dashboard;});};}
for(const name of ['cage:access-closed','cage:session-ready'])window.addEventListener(name,()=>{epoch++;db=null;loaded=0;loading=false;busy=false;scanBusy=false;selected=null;dialog?.close();if(dialog)dialog.innerHTML='';render();if(name==='cage:session-ready')refresh(true);});
window.addEventListener('cage:work-scope',render);
window.CAGE_OPPORTUNITIES={mount,refresh};mount();
})();
